import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../core/providers.dart';
class AddTransactionPage extends ConsumerStatefulWidget{final String? accountId,transactionId;final String initialType;const AddTransactionPage({super.key,this.accountId,this.transactionId,this.initialType='credit'});@override ConsumerState<AddTransactionPage> createState()=>_AddTransactionPageState();}
class _AddTransactionPageState extends ConsumerState<AddTransactionPage>{final amount=TextEditingController(),note=TextEditingController(),category=TextEditingController();String type='credit',currency='YER';bool saving=false;@override void initState(){super.initState();type=widget.initialType;_load();}Future<void> _load()async{final cs=await ref.read(currenciesProvider.future);if(cs.isNotEmpty)currency=cs.first.code;if(widget.transactionId!=null){final t=await ref.read(repositoryProvider).transaction(widget.transactionId!);if(t!=null){amount.text=t.amount.toString();note.text=t.note;category.text=t.category;type=t.type;currency=t.currency;}}if(mounted)setState((){});}Future<void> _save()async{final v=double.tryParse(amount.text.replaceAll(',','').trim());if(widget.accountId==null||v==null||v<=0)return;setState(()=>saving=true);final r=ref.read(repositoryProvider);await r.saveTransaction(accountId:widget.accountId!,type:type,amount:v,currency:currency,category:category.text.trim().isEmpty?'عملية':category.text.trim(),note:note.text.trim(),date:DateTime.now());if(mounted){Navigator.pop(context);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.transactionId==null?'إضافة عملية':'تعديل العملية')),body:ListView(padding:const EdgeInsets.all(16),children:[DropdownButtonFormField<String>(initialValue:type,items:const[DropdownMenuItem(value:'credit',child:Text('له')),DropdownMenuItem(value:'debit',child:Text('عليه'))],onChanged:(v){if(v!=null)setState(()=>type=v);},decoration:const InputDecoration(labelText:'نوع العملية')),TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'المبلغ')),TextField(controller:category,decoration:const InputDecoration(labelText:'التصنيف')),TextField(controller:note,maxLines:3,decoration:const InputDecoration(labelText:'الوصف')),const SizedBox(height:20),FilledButton(onPressed:saving?null:_save,child:Text(saving?'جاري الحفظ...':'حفظ'))]));}
